    public static final Map<String, List<String>> STANDING_PERMISSIONS = Map.of(
            "open", List.of("clerk", "steward"), "settle", List.of("clerk", "steward"),
            "void", List.of("clerk", "steward"), "close", List.of("clerk", "steward"),
            "reassign", List.of("steward"), "reopen", List.of("steward"));
    private static final BigDecimal START_FLOOR = new BigDecimal("1.00");
    private static final BigDecimal START_LATE_PCT = new BigDecimal("0.00");
    private static final int START_TERMS = 14;

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** The sheet's today: every date decision and default date in the sheet uses it. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last number given to a claim opened on the sheet; 0 before the first. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** The settings that carry a figure, each value from a from-date: the floor, the late percent, the terms,
     *  each grade's terms (terms-<grade>), the clerk limit, the cap and the proof threshold. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "sheet_setting", joinColumns = @JoinColumn(name = "sheet_id"))
    private List<SheetSetting> settings = new ArrayList<>();

    /** The permission matrix: for an action, the roles that may take it, comma separated; an action with none
     *  keeps the standing rule. Not dated. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "sheet_permission", joinColumns = @JoinColumn(name = "sheet_id"))
    @MapKeyColumn(name = "action")
    @Column(name = "roles", nullable = false)
    private Map<String, String> permissions = new HashMap<>();

    /** The policy date: a claim dated before it rounds half up, on or after it half to even; none means
     *  the sheet's today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** Period numbering from this date: while the sheet's today is on or after it, a claim opened is numbered
     *  within its period; none means off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    protected Sheet() {
    }

    public Sheet(String id, String createdBy, Instant createdAt, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.createdAt = createdAt;
        this.today = today;
    }

    public String getId() {
        return id;
    }

    public String getCreatedBy() {
        return createdBy;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    /** Every value recorded for a setting that carries a figure, by key, then from-date. */
    public List<SheetSetting> getSettings() {
        return settings.stream()
                .sorted(Comparator.comparing(SheetSetting::getKey).thenComparing(SheetSetting::getFromDate))
                .toList();
    }

    /** Record a setting's value from a date, keeping its other values; one already from that date is
     *  replaced. None is a value too (no limit, no cap, a grade using the sheet's terms). */
    public void setSetting(String key, LocalDate from, String value) {
        settings.removeIf(s -> s.getKey().equals(key) && s.getFromDate().equals(from));
        settings.add(new SheetSetting(key, from, value));
    }

    /** The value of a setting in force on a date: the one with the latest from-date on or before it; empty
     *  when none is recorded by then, null inside when the one in force is none. */
    private Optional<SheetSetting> inForce(String key, LocalDate date) {
        return settings.stream()
                .filter(s -> s.getKey().equals(key) && !s.getFromDate().isAfter(date))
                .max(Comparator.comparing(SheetSetting::getFromDate));
    }

    private BigDecimal decimalOn(String key, LocalDate date, BigDecimal start) {
        return inForce(key, date).map(s -> s.getValue() == null ? null : new BigDecimal(s.getValue())).orElse(start);
    }

    /** The largest due a clerk may settle, in force on the sheet's today; none when there is no limit. */
    public BigDecimal getClerkLimit() {
        return decimalOn(CLERK_LIMIT, today, null);
    }

    /** The least a claim's live due can be on a date; 1.00 before every from-date. */
    public BigDecimal floorOn(LocalDate date) {
        return decimalOn(FLOOR, date, START_FLOOR);
    }

    /** The floor in force on the sheet's today. */
    public BigDecimal getFloor() {
        return floorOn(today);
    }

    /** The most a person's due-total can be, in force on the sheet's today; none when there is no cap. */
    public BigDecimal getCap() {
        return decimalOn(CAP, today, null);
    }

    /** The proof threshold in force on a date: a claim dated then whose due is above it needs a proof to be
     *  settled or approved; none when there is no threshold. */
    public BigDecimal proofThresholdOn(LocalDate date) {
        return decimalOn(PROOF_THRESHOLD, date, null);
    }

    /** The proof threshold in force on the sheet's today; none when there is no threshold. */
    public BigDecimal getProofThreshold() {
        return proofThresholdOn(today);
    }

    /** A person's due-total as it counts: at most the cap; none (n/a) stays none. */
    public BigDecimal capped(BigDecimal dueTotal) {
        BigDecimal cap = getCap();
        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
    }

    /** The sheet's terms on a date; 14 before every from-date. */
    public int termsOn(LocalDate date) {
        return inForce(TERMS, date).map(s -> Integer.valueOf(s.getValue())).orElse(START_TERMS);
    }

    /** The sheet's terms in force on its today. */
    public int getTerms() {
        return termsOn(today);
    }

    /** A grade's own terms on a date; none when it uses the sheet's terms then. */
    public Integer gradeTermsOn(String grade, LocalDate date) {
        return inForce(TERMS + "-" + grade, date).map(SheetSetting::getValue).map(Integer::valueOf).orElse(null);
    }

    /** The grades with their own terms in force on the sheet's today, and their terms. */
    public Map<String, Integer> getGradeTerms() {
        Map<String, Integer> out = new TreeMap<>();
        settings.stream().map(SheetSetting::getKey).filter(k -> k.startsWith(TERMS + "-")).distinct()
                .forEach(k -> {
                    String grade = k.substring(TERMS.length() + 1);
                    Integer own = gradeTermsOn(grade, today);
                    if (own != null) {
                        out.put(grade, own);
                    }
                });
        return out;
    }

    /** The terms of a grade on a date: its own, else the sheet's (the sheet's for no grade). */
    public int termsFor(String grade, LocalDate date) {
        Integer own = grade == null ? null : gradeTermsOn(grade, date);
        return own != null ? own : termsOn(date);
    }

    /** The late percent on a date; 0.00 before every from-date. */
    public BigDecimal latePctOn(LocalDate date) {
        return decimalOn(LATE_PCT, date, START_LATE_PCT);
    }

    /** The late percent in force on the sheet's today. */
    public BigDecimal getLatePct() {
        return latePctOn(today);
    }

    /** The roles typed for each action in the permission matrix; an action not here keeps the standing rule. */
    public Map<String, String> getPermissions() {
        return new TreeMap<>(permissions);
    }

    /** Set the roles that may take an action, comma separated; blank keeps the standing rule. */
    public void setPermission(String action, String roles) {
        if (roles == null || roles.isBlank()) {
            permissions.remove(action);
        } else {
            permissions.put(action, roles);
        }
    }

    /** Whether a role may take an action: by the permission matrix, else by the standing rule. */
    public boolean allows(String action, String role) {
        String typed = permissions.get(action);
        List<String> allowed = typed == null ? STANDING_PERMISSIONS.getOrDefault(action, List.of())
                : Arrays.stream(typed.split(",")).map(String::trim).toList();
        return allowed.contains(role);
    }

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    /** Whether a claim opened now is numbered within its period: the setting is a date and today is on or
     *  after it. */
    public boolean numbersByPeriod() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /** How a claim dated on a date rounds its figures: half up before the policy date (the sheet's today
     *  when it has none), half to even on or after it. */
    public RoundingMode rounding(LocalDate date) {
        LocalDate policy = policyDate == null ? today : policyDate;
        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The late charge on an overdue claim's figure: the late percent in force on the claim's date, of the
     *  figure for every full 30 days past its due-by on the sheet's today, rounded to cents as its date rounds;
     *  0.00 for no figure (n/a). Only an OPEN or PENDING claim is overdue, so the caller asks only for those. */
    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy, LocalDate date) {
        long late = ChronoUnit.DAYS.between(dueBy, today);
        if (figure == null || late < 30) {
            return BigDecimal.ZERO.setScale(2);
        }
        return figure.multiply(latePctOn(date)).multiply(BigDecimal.valueOf(late / 30)).movePointLeft(2)
                .setScale(2, rounding(date));
    }

    /** A live due of a claim dated on a date as it counts: at least the floor in force then; none (n/a)
     *  stays none. */
    public BigDecimal floored(BigDecimal due, LocalDate date) {
        return due == null ? null : due.max(floorOn(date));
    }

    /** Give out the sheet's next claim number. */
    public String nextClaimNumber() {
        return String.valueOf(++lastClaimNumber);
    }
}
package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.Rollup;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Loads sheets by id; a sheet never loaded before is started empty, its today the real date. */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final ClaimSequenceRepository sequences;
    private final PeriodRepository periods;
    private final Rollup rollup;
    private final Audit audit;

    public SheetService(SheetRepository sheets, ClaimSequenceRepository sequences, PeriodRepository periods,
            Rollup rollup, Audit audit) {
        this.sheets = sheets;
        this.sequences = sequences;
        this.periods = periods;
        this.rollup = rollup;
        this.audit = audit;
    }

    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
            } catch (DataIntegrityViolationException e) {
                // Another user started the same sheet at the same moment.
                return sheets.findById(id).orElseThrow(() -> e);
            }
        });
    }

    /** The sheet's today. Every date decision and default date in the sheet goes through this. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseThrow(SheetNotFoundException::new);
    }

    /** Change the sheet's today, recording the figures it moves. */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = sheets.findById(id).orElseThrow(SheetNotFoundException::new);
        Rollup.Snapshot before = rollup.take(id);
        sheet.setToday(today);
        rollup.recordChanges(id, user, before);
        return sheet;
    }

    /** Record the sheet's clerk limit from a date (none: the sheet's today): the largest due a clerk may
     *  settle; none for no limit. */
    @Transactional
    public Sheet setClerkLimit(String id, String user, BigDecimal limit, LocalDate from) {
        return setDated(id, user, Sheet.CLERK_LIMIT, limit == null ? null : limit.setScale(2).toPlainString(), from,
                false);
    }

    /** Record the sheet's floor from a date (none: the sheet's today): the least a claim's live due can be,
     *  recording the figures it moves. */
    @Transactional
    public Sheet setFloor(String id, String user, BigDecimal floor, LocalDate from) {
        return setDated(id, user, Sheet.FLOOR, floor.setScale(2).toPlainString(), from, true);
    }

    /** Record the sheet's cap from a date (none: the sheet's today): the most a person's due-total can be
     *  (none: no cap), recording the figures it moves. */
    @Transactional
    public Sheet setCap(String id, String user, BigDecimal cap, LocalDate from) {
        return setDated(id, user, Sheet.CAP, cap == null ? null : cap.setScale(2).toPlainString(), from, true);
    }

    /** Record the sheet's proof threshold from a date (none: the sheet's today): a claim dated then whose due
     *  is above it needs a proof to be settled or approved; none for no threshold. */
    @Transactional
    public Sheet setProofThreshold(String id, String user, BigDecimal threshold, LocalDate from) {
        return setDated(id, user, Sheet.PROOF_THRESHOLD, threshold == null ? null : threshold.setScale(2).toPlainString(),
                from, false);
    }

    /** Record the sheet's terms from a date (none: the sheet's today): the number of days after a claim's
     *  date it is due by, for a claim added later dated then whose grade has no terms of its own. A claim
     *  already added keeps its due-by. */
    @Transactional
    public Sheet setTerms(String id, String user, int terms, LocalDate from) {
        return setDated(id, user, Sheet.TERMS, Integer.toString(terms), from, false);
    }

    /** Record a grade's own terms from a date (none: the sheet's today; no terms: it uses the sheet's
     *  terms), for a claim added later. A claim already added keeps its due-by. */
    @Transactional
    public Sheet setGradeTerms(String id, String user, String grade, Integer terms, LocalDate from) {
        return setDated(id, user, Sheet.TERMS + "-" + grade, terms == null ? null : terms.toString(), from, false);
    }

    /** Record the sheet's late percent from a date (none: the sheet's today), recording the figures it
     *  moves. */
    @Transactional
    public Sheet setLatePct(String id, String user, BigDecimal latePct, LocalDate from) {
        return setDated(id, user, Sheet.LATE_PCT, latePct.setScale(2).toPlainString(), from, true);
    }

    /** Record a dated setting's value (none: blank) from a date, the sheet's today when none is given,
     *  replacing one already from that date; when it can move figures, record those that moved. */
    private Sheet setDated(String id, String user, String key, String value, LocalDate from, boolean movesFigures) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        Rollup.Snapshot before = movesFigures ? rollup.take(id) : null;
        sheet.setSetting(key, from == null ? sheet.getToday() : from, value);
        sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=" + key + " value="
                + (value == null ? "" : value) + (from == null ? "" : " from=" + from));
        if (movesFigures) {
            rollup.recordChanges(id, user, before);
        }
        return sheet;
    }

    /** Change the sheet's policy date (none: the sheet's today), recording the figures it moves. */
    @Transactional
    public Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        Rollup.Snapshot before = rollup.take(id);
        sheet.setPolicyDate(policyDate);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=policy-date value="
                + (policyDate == null ? "" : policyDate.toString()));
        rollup.recordChanges(id, user, before);
        return sheet;
    }

    /** Set the roles that may take an action (open, settle, void, reassign, close or reopen), comma
     *  separated; blank keeps the standing rule. Not dated. */
    @Transactional
    public Sheet setPermission(String id, String user, String action, String roles) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        String value = roles == null ? "" : roles.trim();
        sheet.setPermission(action, value);
        sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=perm-" + action + " value=" + value);
        return sheet;
    }

    /** Change the sheet's period numbering from-date (none: off). */
    @Transactional
    public Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        sheet.setPeriodNumberingFrom(from);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
                + (from == null ? "" : from.toString()));
        return sheet;
    }

    /** The next number for a claim dated on a date: while the sheet numbers by period, the next in the
     *  sequence of the period containing the date (<period name>-1, -2, ...), or of no period (X-1, ...);
     *  otherwise the sheet-wide one (1, 2, ...). None is ever given twice. */
    @Transactional
    public String nextClaimNumber(String id, LocalDate date) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        if (!sheet.numbersByPeriod()) {
            return sheet.nextClaimNumber();
        }
        String prefix = periods.findBySheetIdOrderByFromDateAsc(id).stream()
                .filter(p -> p.contains(date)).findFirst().map(Period::getName).orElse("X");
        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(id, prefix)
                .orElseGet(() -> new ClaimSequence(id, prefix));
        String number = sequence.nextClaimNumber();
        sequences.save(sequence);
        return number;
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Sheet endpoints. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets")
public class SheetController {

    /** A sheet as the screen shows it: its today, its clerk limit (two decimals; none for no limit) and
     *  its floor (two decimals), its terms (days), its late percent (two decimals) and its policy date (none: the sheet's today) and its period numbering from-date (none: off), the terms of each grade that has its own, and its cap (two decimals; none for no cap), and its proof threshold (two decimals; none for no threshold).
     *  The dated settings show the value in force on the sheet's today; every value recorded for them is in
     *  settings. */
    public record SheetView(String id, LocalDate today, String clerkLimit, String floor, int terms, String latePct,
            LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, String cap,
            List<SettingView> settings, String proofThreshold, Map<String, String> permissions) {

        static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday(),
                    sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                    sheet.getFloor().toPlainString(), sheet.getTerms(),
                    sheet.getLatePct().toPlainString(), sheet.getPolicyDate(),
                    sheet.getPeriodNumberingFrom(), sheet.getGradeTerms(),
                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
                    sheet.getSettings().stream().map(SettingView::of).toList(),
                    sheet.getProofThreshold() == null ? null : sheet.getProofThreshold().toPlainString(),
                    sheet.getPermissions());
        }
    }

    /** A value recorded for a dated setting (key floor, late-pct, terms, terms-<grade>, clerk-limit, cap or proof-threshold)
     *  from a date; none for no limit, no cap, or a grade using the sheet's terms. */
    public record SettingView(String key, LocalDate from, String value) {

        static SettingView of(SheetSetting setting) {
            return new SettingView(setting.getKey(), setting.getFromDate(), setting.getValue());
        }
    }

    /** The sheet's clerk limit from a date; a missing limit means no limit, a missing date the sheet's today. */
    public record SettingsRequest(@DecimalMin("0.00") @Digits(integer = 13, fraction = 2) BigDecimal clerkLimit,
            LocalDate from) {
    }

    /** The sheet's floor from a date (missing: the sheet's today): the least a claim's live due can be. */
    public record FloorRequest(@NotNull @DecimalMin("0.00") @Digits(integer = 13, fraction = 2) BigDecimal floor,
            LocalDate from) {
    }

    /** The sheet's cap from a date (missing: the sheet's today): the most a person's due-total can be; a
     *  missing one means no cap. */
    public record CapRequest(@DecimalMin("0.00") @Digits(integer = 13, fraction = 2) BigDecimal cap,
            LocalDate from) {
    }

    /** The sheet's proof threshold from a date (missing: the sheet's today); a missing one means none. */
    public record ProofThresholdRequest(@DecimalMin("0.00") @Digits(integer = 13, fraction = 2) BigDecimal proofThreshold,
            LocalDate from) {
    }

    /** The sheet's terms from a date (missing: the sheet's today): the number of days after a claim's date it
     *  is due by. */
    public record TermsRequest(@NotNull @Min(0) @Max(36500) Integer terms, LocalDate from) {
    }

    /** A grade's own terms from a date (missing: the sheet's today); missing terms mean the grade uses the
     *  sheet's terms. */
    public record GradeTermsRequest(@Min(0) @Max(36500) Integer terms, LocalDate from) {
    }

    /** The sheet's late percent from a date (missing: the sheet's today): what an overdue claim's due gains of
     *  its figure for every full 30 days. */
    public record LatePctRequest(@NotNull @DecimalMin("0.00") @Digits(integer = 7, fraction = 2) BigDecimal latePct,
            LocalDate from) {
    }

    /** The sheet's policy date; a missing one means the sheet's today. */
    public record PolicyDateRequest(LocalDate policyDate) {
    }

    /** The sheet's period numbering from-date; a missing one means off. */
    public record PeriodNumberingFromRequest(LocalDate periodNumberingFrom) {
    }

    /** The roles that may take an action, comma separated (clerk, steward); blank keeps the standing rule. */
    public record PermissionRequest(
            @Size(max = 200) @Pattern(regexp = "\\s*((clerk|steward)\\s*(,\\s*(clerk|steward)\\s*)*)?") String roles) {
    }

    public record TodayRequest(@NotNull LocalDate today) {
    }

    private final SheetService service;

    public SheetController(SheetService service) {
        this.service = service;
    }

    /** Load a sheet by id, starting it empty if it was never loaded before. */
    @PostMapping("/{id}/load")
    public SheetView load(@PathVariable @NotBlank @Size(max = 200) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return SheetView.of(service.load(id.trim(), user.trim()));
    }

    /** Change the sheet's today. */
    @PutMapping("/{id}/today")
    public SheetView setToday(@PathVariable @NotBlank @Size(max = 200) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid TodayRequest request) {
        return SheetView.of(service.setToday(id.trim(), user.trim(), request.today()));
    }

    /** Change the sheet's settings. */
    @PutMapping("/{id}/settings")
    public SheetView setSettings(@PathVariable @NotBlank @Size(max = 200) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid SettingsRequest request) {
        return SheetView.of(service.setClerkLimit(id.trim(), user.trim(), request.clerkLimit(), request.from()));
    }

    /** Change the sheet's floor. */
    @PutMapping("/{id}/settings/floor")
    public SheetView setFloor(@PathVariable @NotBlank @Size(max = 200) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid FloorRequest request) {
        return SheetView.of(service.setFloor(id.trim(), user.trim(), request.floor(), request.from()));
    }

    /** Change the sheet's cap. */
    @PutMapping("/{id}/settings/cap")
    public SheetView setCap(@PathVariable @NotBlank @Size(max = 200) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid CapRequest request) {
        return SheetView.of(service.setCap(id.trim(), user.trim(), request.cap(), request.from()));
    }

    /** Change the sheet's proof threshold. */
    @PutMapping("/{id}/settings/proof-threshold")
    public SheetView setProofThreshold(@PathVariable @NotBlank @Size(max = 200) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid ProofThresholdRequest request) {
        return SheetView.of(service.setProofThreshold(id.trim(), user.trim(), request.proofThreshold(), request.from()));
    }

