332	    public Sheet load(String id, String user) {
333	        return sheets.findById(id).orElseGet(() -> {
334	            try {
335	                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
336	            } catch (DataIntegrityViolationException e) {
337	                // Another user started the same sheet at the same moment.
338	                return sheets.findById(id).orElseThrow(() -> e);
339	            }
340	        });
341	    }
