414	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
415	        Rollup.Snapshot before = movesFigures ? rollup.take(id) : null;
416	        sheet.setSetting(key, from == null ? sheet.getToday() : from, value);
