453	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
454	        sheet.setPeriodNumberingFrom(from);
455	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
456	                + (from == null ? "" : from.toString()));
457	        return sheet;
458	    }
