460	    /** The next number for a claim dated on a date: while the sheet numbers by period, the next in the
461	     *  sequence of the period containing the date (<period name>-1, -2, ...), or of no period (X-1, ...);
462	     *  otherwise the sheet-wide one (1, 2, ...). None is ever given twice. */
463	    @Transactional
464	    public String nextClaimNumber(String id, LocalDate date) {
465	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
466	        if (!sheet.numbersByPeriod()) {
467	            return sheet.nextClaimNumber();
468	        }
469	        String prefix = periods.findBySheetIdOrderByFromDateAsc(id).stream()
470	                .filter(p -> p.contains(date)).findFirst().map(Period::getName).orElse("X");
471	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(id, prefix)
472	                .orElseGet(() -> new ClaimSequence(id, prefix));
473	        String number = sequence.nextClaimNumber();
474	        sequences.save(sequence);
475	        return number;
476	    }
