700	import net.officefloor.hq.app.role.RoleService;
701	import net.officefloor.hq.app.rollup.Rollup;
702	import net.officefloor.hq.app.sheet.SheetNotFoundException;
703	import net.officefloor.hq.app.sheet.SheetRepository;
704	import org.springframework.dao.DataIntegrityViolationException;
705	import org.springframework.stereotype.Service;
706	import org.springframework.transaction.annotation.Transactional;
707	
708	/** Keeps each sheet's periods: each uniquely named on the sheet, none overlapping another. */
709	@Service
710	public class PeriodService {
711	
712	    private final PeriodRepository periods;
713	    private final SheetRepository sheets;
714	    private final Rollup rollup;
715	    private final RoleService roles;
716	    private final Audit audit;
717	
718	    public PeriodService(PeriodRepository periods, SheetRepository sheets, Rollup rollup, RoleService roles,
719	            Audit audit) {
720	        this.periods = periods;
721	        this.sheets = sheets;
722	        this.rollup = rollup;
723	        this.roles = roles;
724	        this.audit = audit;
725	    }
726	
727	    @Transactional(readOnly = true)
728	    public List<Period> list(String sheetId) {
729	        if (!sheets.existsById(sheetId)) {
730	            throw new SheetNotFoundException();
731	        }
732	        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
733	    }
734	
735	    @Transactional
736	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
737	        // Locking the sheet makes two users' periods go one after the other, so neither misses an overlap.
738	        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
739	        String n = name.trim();
740	        if (from.isAfter(to)) {
741	            throw new PeriodRefusedException("The from-date must be on or before the to-date.");
742	        }
743	        List<Period> existing = periods.findBySheetIdOrderByFromDateAsc(sheetId);
744	        if (existing.stream().anyMatch(p -> p.getName().equalsIgnoreCase(n))) {
745	            throw new PeriodRefusedException("That period name is already in use.");
746	        }
747	        existing.stream().filter(p -> p.overlaps(from, to)).findFirst().ifPresent(p -> {
748	            throw new PeriodRefusedException("The period overlaps " + p.getName() + ".");
749	        });
750	        Period period;
751	        try {
752	            period = periods.saveAndFlush(new Period(sheetId, n, from, to));
753	        } catch (DataIntegrityViolationException e) {
754	            throw new PeriodRefusedException("That period name is already in use.");
755	        }
756	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user
757	                + " period=" + n + " from=" + from + " to=" + to);
758	        return period;
759	    }
760	
761	    /** Close a period, fixing each person's due-total for it and its own as it is now; refused when the user's role may not
762	     *  close it, or it is already closed. */
763	    @Transactional
764	    public Period close(String sheetId, String user, long periodId) {
765	        // Locking the sheet makes the close and any claim change on the sheet go one after the other.
766	        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
767	        Period period = periods.findByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
768	        roles.require(sheetId, user, "close");
769	        if (period.isClosed()) {
770	            throw new PeriodRefusedException("The period is already closed.");
771	        }
772	        period.close(rollup.dueBetweenByPerson(sheetId, period.getFromDate(), period.getToDate()));
773	        periods.saveAndFlush(period);
774	        BigDecimal total = period.getClosedTotal();
775	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user
776	                + " period=" + period.getName() + " total=" + total.toPlainString());
777	        return period;
778	    }
779	
780	    /** Reopen a closed period, making its due-total live again; by a role the sheet allows (a steward
781	     *  by the standing rule), and refused when it is open. */
782	    @Transactional
783	    public Period reopen(String sheetId, String user, long periodId) {
784	        // Locking the sheet makes the reopen and any claim change on the sheet go one after the other.
785	        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
786	        Period period = periods.findByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
787	        roles.require(sheetId, user, "reopen");
788	        if (!period.isClosed()) {
789	            throw new PeriodRefusedException("The period is not closed.");
790	        }
791	        period.reopen();
792	        periods.saveAndFlush(period);
793	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + period.getName());
794	        return period;
795	    }
796	}
