      const cap = this.capTouched() || pick === 'cap'
        || (guess && this.cap().trim() !== (this.session.cap() ?? ''));
      const proofThreshold = this.proofThresholdTouched() || pick === 'proof-threshold'
        || (guess && this.proofThreshold().trim() !== (this.session.proofThreshold() ?? ''));
